  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Ionic and Covalent Bonds$j$, $j${"readings": [{"title": "Ecclesiastes 4 (King James Version)", "url": "/portal/bible/Ecclesiastes/4"}], "body": "A chemical bond is the attraction that holds atoms together. Ecclesiastes 4:12 says, And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken. Strands woven together are stronger than strands apart, and atoms joined by bonds make substances far different from the separate atoms.\n\nAtoms bond to reach a stable, full outer energy level. In an ionic bond, one atom transfers electrons to another. This usually happens between a metal and a nonmetal. Sodium has one valence electron and chlorine has seven. Sodium gives its electron to chlorine, so sodium becomes a positive ion and chlorine becomes a negative ion. Opposite charges attract, and the ions pack into a repeating crystal. Ionic compounds such as table salt, NaCl, are usually hard and brittle, have high melting points, and conduct electricity when melted or dissolved in water. When the charges of the ions are balanced, the formula follows. A magnesium ion has a charge of positive 2 and a chloride ion has a charge of negative 1, so the formula is MgCl2.\n\nIn a covalent bond, atoms share electrons. This usually happens between nonmetals. The result is a molecule. In water, each hydrogen shares a pair of electrons with oxygen. In a single bond one pair is shared, in a double bond two pairs are shared, as in carbon dioxide, and in a triple bond three pairs are shared, as in nitrogen gas. Covalent compounds usually have lower melting points than ionic compounds and do not conduct electricity well. When the sharing is unequal, the molecule is polar, as water is, and this helps water dissolve many substances.\n\nIn a metallic bond, metal atoms share a sea of freely moving electrons, which explains why metals conduct electricity and can be shaped without breaking.\n\nYour task: (1) Tell how an ionic bond differs from a covalent bond. (2) Predict which bond forms between two elements. (3) Write a formula from the ion charges.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Ecclesiastes 4:12 says, a threefold cord is not quickly broken. Strands woven together are stronger than strands apart, and atoms joined by bonds make substances far different from separate atoms.\n\nNow watch this. In an ionic bond, one atom transfers electrons to another, usually between a metal and a nonmetal. Sodium gives one electron to chlorine. Sodium becomes a positive ion, chlorine a negative ion, and the opposite charges attract. Table salt, NaCl, is hard and brittle with a high melting point. Magnesium has a charge of positive 2 and chloride negative 1, so the formula is MgCl2.\n\nIn a covalent bond, atoms share electrons, usually between nonmetals. That makes a molecule. In water, each hydrogen shares a pair of electrons with oxygen. Carbon dioxide has double bonds. Nitrogen gas has a triple bond. Water is polar, which helps it dissolve many substances.\n\nIn a metallic bond, metal atoms share a sea of moving electrons, which is why metals conduct electricity.\n\nYour task is to compare ionic and covalent bonds, predict a bond and write a formula. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Ionic and Covalent Bonds$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Chemical Formulas and Balanced Equations$j$, $j${"readings": [{"title": "Colossians 1 (King James Version)", "url": "/portal/bible/Colossians/1"}], "body": "A chemical reaction rearranges atoms into new substances. Colossians 1:17 says, And he is before all things, and by him all things consist. The matter of the universe holds together by His power, and in every chemical reaction not one atom is lost.\n\nA chemical equation is a short way to describe a reaction. The reactants, which are the starting substances, are written on the left, and the products, which are the new substances, are written on the right, with an arrow read as yields. For example, hydrogen burning in oxygen to make water is written H2 + O2 yields H2O.\n\nThe law of conservation of mass, first stated clearly by Antoine Lavoisier, says that in a chemical reaction mass is neither created nor destroyed. The same number of each kind of atom must appear on both sides. The equation H2 + O2 yields H2O has 2 oxygen atoms on the left and only 1 on the right, so it is not balanced.\n\nTo balance an equation, change only the coefficients, the large numbers in front of formulas. Never change the subscripts, because that would change the substance. Count the atoms of each element, adjust a coefficient, and count again. Put a 2 in front of H2O, which gives 2 oxygen atoms on each side, but now there are 4 hydrogen atoms on the right, so put a 2 in front of H2. The balanced equation is 2H2 + O2 yields 2H2O. The coefficient multiplies every atom in the formula, so 2H2O has 4 hydrogen atoms and 2 oxygen atoms.\n\nAnother example: magnesium burning is Mg + O2 yields MgO. Balancing gives 2Mg + O2 yields 2MgO, with 2 magnesium and 2 oxygen atoms on each side. Rusting is 4Fe + 3O2 yields 2Fe2O3, with 4 iron atoms and 6 oxygen atoms on each side.\n\nYour task: (1) Identify reactants and products. (2) Count atoms on each side. (3) Balance a simple equation using coefficients.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Colossians 1:17 says, And he is before all things, and by him all things consist. The matter of the universe holds together by His power, and in every chemical reaction not one atom is lost.\n\nNow watch this. In a chemical equation, the reactants are on the left and the products are on the right, joined by an arrow that we read as yields. The law of conservation of mass says mass is neither created nor destroyed, so each kind of atom must appear the same number of times on both sides.\n\nLook at hydrogen burning in oxygen. H2 + O2 yields H2O has 2 oxygen atoms on the left and 1 on the right, so it is not balanced. We change only the coefficients, never the subscripts. Put a 2 in front of H2O, then a 2 in front of H2. The balanced equation is 2H2 + O2 yields 2H2O. Now there are 4 hydrogen and 2 oxygen on each side.\n\nMagnesium burning balances as 2Mg + O2 yields 2MgO. Rusting balances as 4Fe + 3O2 yields 2Fe2O3.\n\nYour task is to name reactants and products, count atoms and balance an equation. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Chemical Formulas and Balanced Equations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Types of Chemical Reactions$j$, $j${"readings": [{"title": "1 Peter 1 (King James Version)", "url": "/portal/bible/1Peter/1"}], "body": "Chemical reactions fall into patterns. First Peter 1:7 speaks of the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire. Fire is a chemical reaction, and the refiner's fire shows how a reaction can reveal and purify.\n\nIn a synthesis reaction, two or more substances combine to form one product, A + B yields AB. Hydrogen and oxygen forming water is synthesis. In a decomposition reaction, one compound breaks into simpler substances, AB yields A + B. Passing electricity through water gives 2H2O yields 2H2 + O2. In a single replacement reaction, one element takes the place of another in a compound, as in Zn + 2HCl yields ZnCl2 + H2. In a double replacement reaction, two compounds exchange partners, and often a solid called a precipitate forms, as in AgNO3 + NaCl yields AgCl + NaNO3. In a combustion reaction, a substance burns in oxygen and releases energy. Burning methane gives CH4 + 2O2 yields CO2 + 2H2O.\n\nReactions also involve energy. An exothermic reaction releases energy to the surroundings, as when a fuel burns or a hand warmer works. An endothermic reaction absorbs energy, as when a cold pack feels cold. Photosynthesis is endothermic. Plants use light to turn carbon dioxide and water into sugar and oxygen, 6CO2 + 6H2O + light yields C6H12O6 + 6O2. Cellular respiration is the reverse process and releases energy for the cell.\n\nHow do you know a chemical reaction happened? Look for evidence: a gas forming as bubbles, a precipitate, a permanent color change, heat or light given off, or a new odor. A change in size, shape or state alone is physical. Rusting and burning also involve oxidation, where a substance combines with oxygen.\n\nYour task: (1) Classify a reaction by type. (2) Tell whether a reaction is exothermic or endothermic. (3) List evidence of a chemical change.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, First Peter 1:7 speaks of the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire. Fire is a chemical reaction, and the refiner's fire shows how a reaction can reveal and purify.\n\nNow watch this. In synthesis, substances combine to make one product. In decomposition, one compound breaks into simpler substances, like water splitting into hydrogen and oxygen. In single replacement, one element takes the place of another, like zinc and hydrochloric acid. In double replacement, two compounds trade partners and often a solid forms, called a precipitate. In combustion, a substance burns in oxygen. Methane burning gives carbon dioxide and water.\n\nLook at energy. An exothermic reaction releases energy, like a burning fuel or a hand warmer. An endothermic reaction absorbs energy, like a cold pack. Photosynthesis is endothermic, because plants use light to make sugar and oxygen.\n\nHow do you know a reaction happened? Look for bubbles of gas, a precipitate, a permanent color change, heat or light, or a new odor.\n\nYour task is to classify a reaction, tell exothermic from endothermic and list evidence of change. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Types of Chemical Reactions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Reaction Rates, Acids and Bases$j$, $j${"readings": [{"title": "Matthew 5 (King James Version)", "url": "/portal/bible/Matthew/5"}], "body": "Reactions happen at different speeds, and some liquids are acids or bases. Matthew 5:13 says, Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted? Salt is a compound formed when an acid and a base react, and Jesus used it to teach about usefulness.\n\nReaction rate is how fast reactants turn into products. Collisions between particles cause reactions, so anything that makes collisions more frequent or more energetic speeds a reaction. Raising the temperature, increasing the concentration, and increasing the surface area, for example by crushing a tablet, all speed a reaction. A catalyst speeds a reaction without being used up. Enzymes are catalysts in living cells, and they let digestion happen quickly at body temperature.\n\nAn acid tastes sour, turns blue litmus red, and releases hydrogen ions in water. Examples are vinegar, lemon juice and stomach acid. A base tastes bitter, feels slippery, turns red litmus blue, and releases hydroxide ions in water. Examples are soap, baking soda and ammonia cleaners. Never taste or touch unknown chemicals, because strong acids and bases burn.\n\nThe pH scale runs from 0 to 14. A pH below 7 is acidic, a pH of 7 is neutral, as pure water is, and a pH above 7 is basic. Each step on the scale is a change of ten times in acidity. Stomach acid is about pH 1 to 2, lemon juice about 2, black coffee about 5, blood about 7.4, baking soda solution about 9, and household bleach about 12 to 13. Indicators such as litmus and phenolphthalein change color to show acid or base.\n\nWhen an acid and a base react, they neutralize each other and form a salt and water. For example, HCl + NaOH yields NaCl + H2O. Antacid tablets use this to settle stomach acid.\n\nYour task: (1) List four ways to speed up a reaction. (2) Classify a solution as acidic, basic or neutral from its pH. (3) Write what forms when an acid neutralizes a base.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Matthew 5:13 says, Ye are the salt of the earth. Salt is a compound formed when an acid and a base react, and Jesus used it to teach about usefulness.\n\nNow watch this. Reaction rate is how fast reactants turn into products. Particles must collide, so a higher temperature, a higher concentration or a larger surface area speeds a reaction. A catalyst speeds a reaction without being used up. Enzymes are catalysts in living cells.\n\nLook at acids and bases. An acid is sour and releases hydrogen ions in water, like vinegar and lemon juice. A base is bitter and slippery and releases hydroxide ions, like soap and baking soda. Never taste or touch unknown chemicals.\n\nThe pH scale runs from 0 to 14. Below 7 is acidic. Seven is neutral, like pure water. Above 7 is basic. Each step is a change of ten times. Stomach acid is about 1 to 2. Bleach is about 12 to 13.\n\nWhen an acid and a base react, they neutralize each other and form a salt and water. HCl plus NaOH yields NaCl plus water.\n\nYour task is to list ways to speed a reaction, classify solutions by pH and describe neutralization. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Reaction Rates, Acids and Bases$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Chemical Bonds and Reactions$j$, $j${"prompt": "Write a report of at least 250 words on chemical bonds and reactions. Use complete sentences, show your work and label each part. Colossians 1:17 says, And he is before all things, and by him all things consist.\n\nPart 1: Describe how sodium and chlorine form an ionic bond, and how hydrogen and oxygen form covalent bonds in water. Tell two properties that differ between ionic and covalent compounds.\nPart 2: Balance these equations and show your atom counts: H2 + O2 yields H2O, then N2 + H2 yields NH3, then Mg + O2 yields MgO.\nPart 3: Classify each reaction as synthesis, decomposition, single replacement, double replacement or combustion: 2H2O yields 2H2 + O2, then Zn + 2HCl yields ZnCl2 + H2, then CH4 + 2O2 yields CO2 + 2H2O. Tell whether burning is exothermic or endothermic.\nPart 4: Explain four ways to speed up a reaction and what a catalyst does.\nPart 5: Tell whether solutions with pH values of 2, 7 and 11 are acidic, basic or neutral, describe what neutralization makes, and explain how Matthew 5:13 connects to salt.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Chemical Bonds and Reactions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Bonds That Hold$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a bond between people in your family, church or team that holds strong, (2) explains how atoms bond by sharing or transferring electrons to become stable, (3) tells how the idea that no atom is lost in a reaction shows the order of creation, and (4) connects your answer to Ecclesiastes 4:12, Colossians 1:17 or Matthew 5:13. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What can believers learn about unity from the way atoms bond? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Bonds That Hold$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Ionic and Covalent Bonds$j$, $j${"questions": [{"q": "An ionic bond forms when:", "options": ["Electrons are shared equally", "Electrons are transferred from one atom to another", "Neutrons are exchanged", "Protons are shared"]}, {"q": "A covalent bond forms when atoms:", "options": ["Gain protons", "Share electrons", "Lose neutrons", "Transfer all their electrons"]}, {"q": "Which compound is held together by ionic bonds?", "options": ["H2O", "CO2", "O2", "NaCl"]}, {"q": "Water is a molecule because its atoms are joined by:", "options": ["Covalent bonds", "Magnetic bonds", "Ionic bonds", "Nuclear bonds"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Ionic and Covalent Bonds$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$Ionic bonds come from electron transfer.$j$,$j$Covalent bonds are shared pairs of electrons.$j$,$j$Sodium is a metal and chlorine is a nonmetal.$j$,$j$Hydrogen and oxygen share electrons.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Ionic and Covalent Bonds$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Chemical Formulas and Balanced Equations$j$, $j${"questions": [{"q": "In a chemical equation, the substances on the left side are the:", "options": ["Isotopes", "Products", "Catalysts", "Reactants"]}, {"q": "The law of conservation of mass says that in a chemical reaction:", "options": ["Mass always increases", "Atoms disappear", "Mass is neither created nor destroyed", "The products always weigh less"]}, {"q": "Which equation is balanced?", "options": ["H2 + O2 yields H2O", "2H2 + O2 yields 2H2O", "H2 + O2 yields 2H2O", "2H2 + 2O2 yields 2H2O"]}, {"q": "To balance an equation you change the:", "options": ["Coefficients", "Charges", "Element symbols", "Subscripts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Chemical Formulas and Balanced Equations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,1,0}'::int[], array[$j$Reactants are the starting substances.$j$,$j$The total mass stays the same.$j$,$j$Only the first has equal atoms of each element on both sides.$j$,$j$Changing subscripts would change the substance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Chemical Formulas and Balanced Equations$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Types of Chemical Reactions$j$, $j${"questions": [{"q": "A reaction in which one compound breaks down into simpler substances is:", "options": ["Neutralization", "Decomposition", "Synthesis", "Combustion"]}, {"q": "Burning methane in oxygen to make carbon dioxide and water is a:", "options": ["Neutralization reaction", "Decomposition reaction", "Combustion reaction", "Physical change"]}, {"q": "A reaction that releases energy to its surroundings is:", "options": ["Reversible", "Exothermic", "Endothermic", "Inert"]}, {"q": "Which is evidence of a chemical reaction?", "options": ["A change in size", "Sugar dissolving in water", "A change in shape", "Bubbles of gas and a permanent color change"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Types of Chemical Reactions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,3}'::int[], array[$j$Decomposition splits a compound apart.$j$,$j$Burning in oxygen is combustion.$j$,$j$Exothermic reactions give off energy.$j$,$j$Gas and a new color suggest new substances.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Types of Chemical Reactions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Reaction Rates, Acids and Bases$j$, $j${"questions": [{"q": "A catalyst:", "options": ["Always slows a reaction", "Is a reactant that gets used up", "Is a product of the reaction", "Speeds up a reaction without being used up"]}, {"q": "A solution with a pH of 3 is:", "options": ["Basic", "Neutral", "Acidic", "A pure base"]}, {"q": "The pH of pure water is:", "options": ["7", "14", "0", "1"]}, {"q": "The products of neutralizing an acid with a base are:", "options": ["Two metals", "Two gases", "A salt and water", "An acid and a base"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Reaction Rates, Acids and Bases$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,0,2}'::int[], array[$j$A catalyst is not consumed.$j$,$j$A pH below 7 is acidic.$j$,$j$Pure water is neutral.$j$,$j$Neutralization forms a salt and water.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Reaction Rates, Acids and Bases$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Chemical Bonds and Reactions$j$, $j${"questions": [{"q": "Sodium gives an electron to chlorine. The bond formed is:", "options": ["Ionic", "Metallic", "Covalent", "Nuclear"]}, {"q": "A bond in which two atoms share electrons is:", "options": ["Nuclear", "Covalent", "Ionic", "Magnetic"]}, {"q": "How many oxygen atoms are in 2H2O?", "options": ["1", "4", "3", "2"]}, {"q": "In 2Mg + O2 yields 2MgO, the coefficient in front of MgO is:", "options": ["1", "3", "4", "2"]}, {"q": "Zn + 2HCl yields ZnCl2 + H2 is a:", "options": ["Decomposition reaction", "Single replacement reaction", "Synthesis reaction", "Combustion reaction"]}, {"q": "Raising the temperature usually makes a reaction:", "options": ["Slower", "Faster", "Stop", "Impossible"]}, {"q": "Which pH value is the most basic?", "options": ["1", "13", "7", "3"]}, {"q": "Which is NOT a sign of a chemical change?", "options": ["A new color appearing", "Heat or light given off", "Gas bubbles forming", "Ice melting"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Chemical Bonds and Reactions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,3,1,1,1,3}'::int[], array[$j$Electron transfer makes an ionic bond.$j$,$j$Sharing electrons is a covalent bond.$j$,$j$The coefficient 2 times 1 oxygen gives 2.$j$,$j$The number in front of MgO is 2.$j$,$j$Zinc replaces hydrogen.$j$,$j$Particles collide more often and with more energy.$j$,$j$The highest pH is the most basic.$j$,$j$Melting is a physical change.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Chemical Bonds and Reactions$j$ on conflict (item_id) do nothing;
